import { operation, resource } from "@tinker/core";

import { database } from "~/components/database/index.server";
import { requestHeaders } from "~/components/requests/index.server";

import { authCalls } from "./calls.server";
import { betterAuthModule, betterAuthDrizzle, betterAuthStart } from "./modules";
import * as schema from "./schema.server";
import { authSettings, authStartup } from "./settings.server";
import { sendAuthMail, sessionDeleted } from "./slots";

/**
 * The root tracks each mail action; auth callbacks return before delivery.
 * A session delete sends the account notice after its commit: sign-out, a revoked or deleted
 * session, and a deleted user (its sessions go through the same delete) all end here.
 */
export const auth = resource({
  label: "auth",
  depends: {
    database,
    settings: authSettings,
    calls: authCalls,
    outside: authStartup,
    send: sendAuthMail.required,
    deleted: sessionDeleted.required,
    auth: betterAuthModule,
    adapter: betterAuthDrizzle,
    start: betterAuthStart,
  },
  factory: async ({ database, settings, calls, outside, send, deleted, auth, adapter, start }) => {
    const { betterAuth } = auth;
    const { drizzleAdapter } = adapter;
    const { tanstackStartCookies } = start;
    return betterAuth({
      baseURL: settings.origin,
      secret: settings.secret,
      database: drizzleAdapter(database, { provider: "pg", schema }),
      databaseHooks: {
        session: {
          delete: {
            after: ({ userId }) => calls.fire(deleted, userId, outside),
          },
        },
      },
      emailAndPassword: {
        enabled: true,
        sendResetPassword: async ({ user, url }) => {
          calls.fire(send, { to: user.email, subject: "Reset your password", text: url }, outside);
        },
      },
      emailVerification: {
        sendOnSignUp: true,
        sendVerificationEmail: async ({ user, url }) => {
          calls.fire(send, { to: user.email, subject: "Check your email", text: url }, outside);
        },
      },
      plugins: [tanstackStartCookies()],
    });
  },
});

export const principal = resource({
  label: "request.principal",
  target: "session",
  depends: { auth, headers: requestHeaders },
  factory: async ({ auth, headers }) => (await auth.api.getSession({ headers }))?.user ?? null,
});

/** A long stream rechecks the live cookie without using caches or refreshing the session. */
export const liveAccount = operation({
  label: "sync.liveAccount",
  depends: { auth, headers: requestHeaders },
  run: async ({ auth, headers }) =>
    (
      await auth.api.getSession({
        headers,
        query: { disableCookieCache: true, disableRefresh: true },
      })
    )?.user.id ?? null,
});

import { resource } from "@tinker/core";
import type { Scope } from "@tinker/core";

import { asyncHooks } from "./modules";

/** Keep overlapping calls separate; a detached callback cannot reuse a finished flow. */
export const authCalls = resource({
  label: "auth.calls",
  depends: { hooks: asyncHooks },
  factory: async ({ hooks }, { defer }) => {
    const calls = new hooks.AsyncLocalStorage<Scope.ExtensionCtx>();
    defer(() => calls.disable());
    const live = new WeakSet<Scope.ExtensionCtx>();
    return {
      fire<T, R>(
        hook: (input: T, context: Scope.ExtensionCtx) => R,
        input: T,
        outside: Scope.ExtensionCtx,
      ): R {
        const context = calls.getStore();
        return hook(input, context && live.has(context) ? context : outside);
      },
      run(context: Scope.ExtensionCtx, next: () => unknown) {
        live.add(context);
        return calls.run(context, () => {
          try {
            const result = next();
            if (result instanceof Promise) return result.finally(() => live.delete(context));
            live.delete(context);
            return result;
          } catch (error) {
            live.delete(context);
            throw error;
          }
        });
      },
    };
  },
});

import { operation } from "@tinker/core";
import { z } from "zod";

import { auth } from "./auth.server";

/**
 * ADR 0103's named protocol exception: the app's auth library owns its HTTP contract, so this
 * operation hands it the whole request and returns its reply as is.
 */
export const handleAuth = operation({
  label: "handleAuth",
  input: z.instanceof(Request),
  depends: { auth },
  run: ({ auth }, { input }) => auth.handler(input),
});

export { auth, principal, liveAccount } from "./auth.server";
export { handleAuth } from "./handle.server";
export { authSettings, authStartup } from "./settings.server";
export type { Auth } from "./settings.server";
export { sendAuthMail, sessionDeleted } from "./slots";
export { user, session, account, verification } from "./schema.server";

import { resource } from "@tinker/core";

export const betterAuthModule = resource({
  label: "module:better-auth",
  target: "scope",
  factory: () => import("better-auth"),
});

export const betterAuthDrizzle = resource({
  label: "module:better-auth/adapters/drizzle",
  target: "scope",
  factory: () => import("better-auth/adapters/drizzle"),
});

export const betterAuthStart = resource({
  label: "module:better-auth/tanstack-start",
  target: "scope",
  factory: () => import("better-auth/tanstack-start"),
});

export const asyncHooks = resource({
  label: "module:node:async_hooks",
  factory: () => import("node:async_hooks"),
});

import { pgTable, text, timestamp, boolean, index } from "drizzle-orm/pg-core";

export const user = pgTable("user", {
  id: text().primaryKey(),
  name: text().notNull(),
  email: text().notNull().unique(),
  emailVerified: boolean().notNull().default(false),
  image: text(),
  createdAt: timestamp().notNull().defaultNow(),
  updatedAt: timestamp().notNull().defaultNow(),
});

export const session = pgTable(
  "session",
  {
    id: text().primaryKey(),
    expiresAt: timestamp().notNull(),
    token: text().notNull().unique(),
    createdAt: timestamp().notNull().defaultNow(),
    updatedAt: timestamp().notNull().defaultNow(),
    ipAddress: text(),
    userAgent: text(),
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [index("session_user_id").on(table.userId)],
);

export const account = pgTable(
  "account",
  {
    id: text().primaryKey(),
    accountId: text().notNull(),
    providerId: text().notNull(),
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text(),
    refreshToken: text(),
    idToken: text(),
    accessTokenExpiresAt: timestamp(),
    refreshTokenExpiresAt: timestamp(),
    scope: text(),
    password: text(),
    createdAt: timestamp().notNull().defaultNow(),
    updatedAt: timestamp().notNull().defaultNow(),
  },
  (table) => [index("account_user_id").on(table.userId)],
);

export const verification = pgTable(
  "verification",
  {
    id: text().primaryKey(),
    identifier: text().notNull(),
    value: text().notNull(),
    expiresAt: timestamp().notNull(),
    createdAt: timestamp().notNull().defaultNow(),
    updatedAt: timestamp().notNull().defaultNow(),
  },
  (table) => [index("verification_identifier").on(table.identifier)],
);

import { extension, tag } from "@tinker/core";
import { z } from "zod";

import { authCalls } from "./calls.server";
import { sendAuthMail, sessionDeleted } from "./slots";

export declare namespace Auth {
  type Settings = { origin: string; secret: string };
}

export const authSettings = tag<Auth.Settings>({
  label: "auth.settings",
  parse: z.object({ origin: z.url({ protocol: /^https?$/ }), secret: z.string().min(32) }),
});

/** Check required config at start; retain the start context only for hooks outside a live flow. */
export const authStartup = extension({
  label: "auth",
  hooks: {
    async start(event) {
      event.resolve(authSettings);
      event.resolve(sendAuthMail);
      event.resolve(sessionDeleted);
      await event.next();
      return event;
    },
    run(event) {
      return event.resolve(authCalls).then((calls) => calls.run(event, event.next));
    },
  },
});

import type { Scope } from "@tinker/core";
import { tag } from "@tinker/core";

/** The command binds its owned mail queue; auth never owns delivery. */
export const sendAuthMail = tag<
  (message: { to: string; subject: string; text: string }, context: Scope.ExtensionCtx) => void
>({
  label: "auth.sendMail",
});

/** The command binds the post-commit account notice; auth never imports sync. */
export const sessionDeleted = tag<
  (accountId: string, context: Scope.ExtensionCtx) => Promise<void>
>({
  label: "auth.sessionDeleted",
});

import { createFileRoute } from "@tanstack/react-router";

import { handleAuth } from "~/components/auth/index.server";
import { startRequests } from "~/components/requests/index";
import { readResult } from "~/components/requests/index.server";

/** The copied auth route delegates HTTP to its owned handler; the app's auth library answers. */
export const Route = createFileRoute("/api/auth/$")({
  server: {
    middleware: [startRequests.middleware],
    handlers: {
      GET: async ({ request, context }) =>
        readResult(
          await context.session.settle(handleAuth, { input: request, signal: context.signal }),
        ),
      POST: async ({ request, context }) =>
        readResult(
          await context.session.settle(handleAuth, { input: request, signal: context.signal }),
        ),
    },
  },
});
